{
  "title": "紫禁屋脊决",
  "theme_elements": [
    "紫禁城明黄琉璃瓦屋脊夜景",
    "轻功飞掠帅气入场",
    "连续无停顿的快节奏近身格斗",
    "借势变招的流畅武打设计",
    "克制非血腥的帅气击杀",
    "电影级冷调夜景质感"
  ],
  "story_arc": {
    "goal": "两名顶尖武林高手为争夺象征武林正统的盟主令，相约在紫禁城最高屋脊展开最终对决，胜者将成为武林共主",
    "stakes": "对决全程不得惊扰紫禁城内的值守人员，败者将自废武功退出武林，胜者获得号令全武林的正统地位",
    "turning_point": "交手十余招后双方原本势均力敌，黑衣刀手故意卖出行将落败的破绽，引诱白衣剑手踩上屋脊边缘的松动瓦块借力突进，提前预判对方的剑招变招轨迹",
    "resolution": "最后一方被另一方帅气击杀，以克制、非血腥的画面清楚呈现死亡结果。"
  },
  "characters": [
    {
      "name": "SWORD_WHITE",
      "description": "成年男性，身形挺拔修长，身着月白色绣银竹暗纹的窄袖武侠劲装，高束马尾配素银发带，足蹬黑色软底快靴，手持一柄刃长三尺的精钢长剑，剑刃泛冷冽寒光，剑尾系素白丝绦剑穗",
      "mobility": "bipedal",
      "reference_mode": "identity"
    },
    {
      "name": "BLADE_BLACK",
      "description": "成年男性，身形精悍结实，身着玄色绣云纹的紧身劲装，额间束黑色牛皮抹额，短发利落无饰，足蹬防滑黑色软靴，手持一柄宽背薄刃的玄铁短刀，刀身无纹饰，刀柄缠黑色牛皮防滑",
      "mobility": "bipedal",
      "reference_mode": "identity"
    }
  ],
  "scene_entities": [
    "imperial_glazed_yellow_roof_tiles",
    "bronze_ridge_beast",
    "upturned_eave_corner",
    "loose_roof_tile_segment",
    "night_cold_moon"
  ],
  "locations": [
    {
      "id": "FORBIDDEN_CITY_MAIN_HALL_ROOF",
      "description": "紫禁城太和殿最高处的明黄琉璃瓦主屋脊，屋面坡度平缓，沿屋脊排列多尊铜制脊兽，两端延伸出上翘的飞檐角，下方是深邃幽暗的宫院，夜空澄澈无云，冷月悬于飞檐侧上方，视野开阔无遮挡，适合轻功施展与近身格斗"
    }
  ],
  "mood": "紧绷凌厉，兼具轻功对决的飘逸感与近身格斗的肃杀感，整体氛围克制苍凉，无冗余情绪",
  "music_style": "以急促琵琶轮指搭配厚重堂鼓为核心的武侠电影配乐，交手阶段鼓点随动作节奏逐步加密，击杀瞬间配短促沉实的重音，收尾保留檐间穿堂风的空旷音效"
}

